          "title": "Sección 2: La Atmósfera Aplastante",
          "text": [
            "Su aire es 90 veces más pesado que el nuestro.",
            "Está lleno de dióxido de carbono asfixiante.",
            "Sentirías la presión de estar en el fondo del océano."
          ],
          "image": "https://images-assets.nasa.gov/image/iss006e48523/iss006e48523~medium.jpg",
