            "Si la pequeña y blanca pequeña gordita roba tanto muchísimo gas rico que pesa demasiado y llega a pesar a valer 1.4 veces soles grandes el peso del Sol...",
            "Explotará fatal y ruidosamente y espectacularmente como supernova de tipo Ia luminosa destruyéndose"
